<template><view class="card"><text class="title">完善注册资料</text><text class="hint">留下姓名和手机号，商家才能认出您、及时为您审核和联系。</text><text class="number">您的会员编号：{{member.id}}</text><text class="field-label">姓名</text><!-- #ifdef MP-WEIXIN --><input type="nickname" class="profile-input" v-model="name" @blur="name=$event.detail.value" maxlength="20" placeholder="请填写您的姓名"/><!-- #endif --><!-- #ifndef MP-WEIXIN --><input class="profile-input" v-model="name" maxlength="20" placeholder="请填写您的姓名"/><!-- #endif --><text class="field-label">手机号</text><view v-if="verified" class="verified">{{verified}}（微信已验证）</view><template v-else><!-- #ifdef MP-WEIXIN --><button v-if="!manual" class="ui-button primary" open-type="getPhoneNumber" @getphonenumber="onPhone" :disabled="busy">微信手机号一键填写</button><text v-if="!manual" class="link" @click="manual=true">不方便授权？手动填写手机号</text><!-- #endif --><input v-if="manualShown" class="profile-input" v-model="phone" type="number" maxlength="11" placeholder="请填写11位手机号"/></template><button class="ui-button primary" :disabled="busy" @click="save">完成</button></view></template>
<script>import {request,notify} from '../services/shop.js';import {DEFAULT_NAMES} from '../services/member-profile.js';
export default {props:{member:Object},data(){const name=String(this.member?.nickname||'').trim();return{name:DEFAULT_NAMES.includes(name)?'':name,phone:this.member?.contact_phone||'',verified:this.member?.phone||'',manual:false,busy:false}},
computed:{manualShown(){/* #ifdef MP-WEIXIN */return this.manual;/* #endif */return true}},
methods:{
 async act(fn){if(this.busy)return;this.busy=true;try{await fn()}catch(e){notify(e)}finally{this.busy=false}},
 onPhone(e){const code=e?.detail?.code;if(!code){this.manual=true;notify('没有获取到微信手机号，请手动填写');return}this.act(async()=>{const r=await request('/account/wechat-phone','POST',{code});this.verified=r.phone})},
 save(){this.act(async()=>{const name=String(this.name||'').trim(),phone=String(this.phone||'').replace(/\s/g,'');if(!name||DEFAULT_NAMES.includes(name))throw Error('请填写您的姓名');if(!this.verified&&!/^1[3-9]\d{9}$/.test(phone))throw Error(this.manualShown?'请填写正确的11位手机号':'请点“微信手机号一键填写”，或手动填写手机号');await request('/account/basic-profile','POST',{nickname:name,contactPhone:this.verified?'':phone});uni.showToast({title:'资料已保存',icon:'success'});this.$emit('saved')})}}}</script><style scoped>
@import '../styles/component-base.css';
.card{background:var(--shop-surface, #fdfeff);padding:18px;margin:16px;border-radius:12px;font-size:16px;border:1px solid var(--shop-border, #d5e6ee)}.title{display:block;font-weight:bold;font-size:19px;margin-bottom:6px}.hint{display:block;color:var(--shop-ink, #28546c);line-height:1.6;font-size:14px}.number{display:block;margin-top:10px;font-size:15px;font-weight:bold;color:var(--shop-text, #2b424f)}.field-label{display:block;font-size:14px;margin:14px 0 7px;color:var(--shop-ink, #28546c)}.profile-input{display:block;width:100%;height:46px;min-height:46px;box-sizing:border-box;background:var(--shop-background, #f3f8fb);border:1px solid var(--shop-border, #d5e6ee);border-radius:6px;padding:0 12px;margin:0 0 12px;font-size:16px;line-height:normal;color:var(--shop-text, #2b424f)}.verified{font-size:16px;margin-bottom:12px;color:var(--shop-text, #2b424f)}.link{display:block;font-size:14px;color:var(--shop-ink, #28546c);text-decoration:underline;margin:4px 0 12px}button{font-size:16px;margin:10px 0}</style>
